import os,json,copy
from pathlib import Path
import pandas as pd
import numpy as np
import streamlit as st
import pandas as pd
REQUIRED = ['trade_date','hub','product','strip','contract','settlement_price']

def normalize_prices(df):
    df = df.copy()
    df.columns = [str(c).strip().lower().replace(' ','_') for c in df.columns]
    missing = set(REQUIRED)-set(df.columns)
    if missing: raise ValueError('Missing pricing columns: '+', '.join(sorted(missing)))
    df = df[REQUIRED].copy()
    for col in ['trade_date','strip']:
        df[col] = pd.to_datetime(df[col].astype(str), errors='coerce', format='mixed').dt.normalize()
    df['settlement_price'] = pd.to_numeric(df['settlement_price'], errors='coerce')
    df = df.dropna(subset=REQUIRED)
    for col in ['contract','hub','product']: df[col] = df[col].astype(str).str.strip()
    if df.empty: raise ValueError('No valid pricing records found.')
    return df

def read_prices(source):
    name = str(getattr(source,'name',source)).lower().split('?')[0]
    if hasattr(source,'seek'): source.seek(0)
    if name.endswith('.parquet'): df = pd.read_parquet(source)
    elif name.endswith('.csv'): df = pd.read_csv(source)
    else: df = pd.read_excel(source, sheet_name=0, usecols='A:K')
    return normalize_prices(df)

def curve(prices, asof, selections, months):
    snapshot = prices[prices.trade_date.eq(pd.Timestamp(asof))]
    out = pd.DataFrame(index=pd.DatetimeIndex(months,name='month'))
    for i,(hub,product,contract) in enumerate(selections):
        x = snapshot[(snapshot.hub==hub)&(snapshot['product']==product)&(snapshot.contract==contract)]
        if x.strip.duplicated().any(): raise ValueError('Duplicate settlements for selected product/date; clean the source before pricing.')
        out[f'component_{i+1}'] = x.set_index('strip').settlement_price.reindex(out.index)
    return out


def pricing_file_order(name):
    import re
    match=re.search(r'(20\d{2})[_-](\d{2})[_-](\d{2})',str(name))
    return (''.join(match.groups()) if match else '',str(name))

def extend_index(piece,mode,manual=None):
    piece=piece.copy()
    if mode=='Use file settlements only':return piece
    if mode=='Manual value for missing index months':
        if manual is None:raise ValueError('Enter the missing-month financial index assumption.')
        return piece.fillna(float(manual))
    if mode=='Carry last available index forward':return piece.ffill()
    raise ValueError('Unknown financial index treatment.')


def seasonal_index(history,months):
    """Fill missing months from the prior year's same calendar month, recursively."""
    history=history.copy().sort_index()
    months=pd.DatetimeIndex(months)
    if history.index.duplicated().any():raise ValueError('Duplicate monthly financial index settlements.')
    if not len(months):return pd.Series(dtype=float,index=months)
    available=history.dropna()
    if available.empty:return history.reindex(months)
    first=min(available.index.min(),months.min())
    full=history.reindex(pd.date_range(first,max(history.index.max(),months.max()),freq='MS'))
    for month in full.index:
        if pd.isna(full.loc[month]):
            prior=month-pd.DateOffset(years=1)
            if prior in full.index and pd.notna(full.loc[prior]):full.loc[month]=full.loc[prior]
    return full.reindex(months)

"""Ohio retail gas economics: explicit monthly inputs, storage cash and inventory."""
import numpy as np
import pandas as pd

TERMS=[6,12,18,24,36,48]
ROUTES={'Columbia Gas of Ohio':['TCO'],'Enbridge Gas Ohio (formerly Dominion Energy Ohio)':['East - Eastern Gas','West - TCO']}

def component_weights(utility,route):
    if utility.startswith('Columbia'):return {'H':1.,'TCO':.9,'TIS':.9,'REX':.1,'REI':.1}
    if 'East' in route:return {'H':1.,'DOM':1.,'DIS':1.}
    return {'H':1.,'TCO':1.,'TIS':1.}

def monthly_returns(cash, discount):
    cash=np.asarray(cash,dtype=float)
    if not np.isfinite(cash).all():raise ValueError('Non-finite investment cash flows.')
    discount_monthly=(1+discount)**(1/12)-1
    npv=float(np.sum(cash/(1+discount_monthly)**np.arange(len(cash))))
    irr=None;status='IRR requires negative and positive investment cash flows'
    if (cash<0).any() and (cash>0).any():
        roots=np.polynomial.polynomial.polyroots(cash)
        valid=[float(r.real) for r in roots if abs(r.imag)<1e-7 and r.real>0]
        if len(valid)==1:
            value=(1/valid[0])**12-1
            if np.isfinite(value):irr=value;status='Annual effective IRR'
        elif len(valid)>1:status='Multiple IRRs; no unique return'
        else:status='No valid IRR'
    return npv,irr,status

def route_build(schedule, supply_prices, config):
    x=schedule.copy().reset_index(drop=True)
    required=['sales','ft_capacity_day','ft_rate','commodity_rate','broker_rate','fuel_pct','injection','withdrawal','storage_fixed','injection_fee','withdrawal_fee','injection_loss_pct','withdrawal_loss_pct']
    if 'opex_rate' not in x:x['opex_rate']=0.
    required.append('opex_rate')
    for col in required:
        x[col]=pd.to_numeric(x[col],errors='coerce')
        if x[col].isna().any() or not np.isfinite(x[col]).all() or (x[col]<0).any():raise ValueError(f'Enter finite nonnegative {col} for every contract month.')
    for col in ['fuel_pct','injection_loss_pct','withdrawal_loss_pct']:
        if (x[col]>=100).any():raise ValueError(f'{col} must be below 100%.')
    x['month']=pd.to_datetime(x['month']).dt.to_period('M').dt.to_timestamp()
    if x.month.duplicated().any():raise ValueError('Duplicate delivery months.')
    prices=pd.Series(supply_prices).reindex(pd.DatetimeIndex(x.month))
    if prices.isna().any() or not np.isfinite(prices).all():raise ValueError('Missing forward settlement months for this supply path.')
    x['supply_price']=prices.to_numpy()
    opening=float(config.get('opening_inventory',0));opening_unit=float(config.get('opening_unit_cost',0))
    if opening<0 or opening_unit<0:raise ValueError('Opening inventory and its unit cost must be nonnegative.')
    inventory=opening;book=opening*opening_unit
    max_inventory=config.get('storage_capacity')
    if max_inventory is not None and (max_inventory<0 or opening>max_inventory+1e-7):raise ValueError('Opening inventory exceeds storage capacity.')
    records=[]
    for row in x.itertuples(index=False):
        days=row.month.days_in_month
        withdrawal_delivery=row.withdrawal*(1-row.withdrawal_loss_pct/100)
        if withdrawal_delivery>row.sales+1e-7:raise ValueError(f'{row.month:%Y-%m}: storage withdrawal exceeds customer demand.')
        direct=row.sales-withdrawal_delivery
        gross_direct=direct/(1-row.fuel_pct/100)
        gross_injection=row.injection/(1-row.fuel_pct/100)
        purchases=gross_direct+gross_injection
        purchase_cost=purchases*row.supply_price
        initial_inventory=inventory;initial_book=book
        credited_injection=row.injection*(1-row.injection_loss_pct/100)
        inventory+=credited_injection;book+=gross_injection*row.supply_price
        if max_inventory is not None and inventory>max_inventory+1e-7:raise ValueError(f'{row.month:%Y-%m}: injection exceeds entered storage capacity (before withdrawals).')
        if row.withdrawal>inventory+1e-7:raise ValueError(f'{row.month:%Y-%m}: withdrawal exceeds available inventory.')
        unit=book/inventory if inventory>1e-10 else 0.
        withdrawal_cogs=row.withdrawal*unit
        inventory-=row.withdrawal;book-=withdrawal_cogs
        if abs(inventory)<1e-8:inventory=0.;book=0.
        if config['ft_basis']=='Daily':ft_cost=row.ft_capacity_day*row.ft_rate*days
        else:ft_cost=row.ft_capacity_day*row.ft_rate
        commodity=purchases*row.commodity_rate
        brokerage=row.sales*row.broker_rate
        storage_cost=row.storage_fixed+row.injection*row.injection_fee+row.withdrawal*row.withdrawal_fee
        opex=row.sales*row.opex_rate
        cash_cost=purchase_cost+ft_cost+commodity+brokerage+storage_cost+opex
        cogs=gross_direct*row.supply_price+withdrawal_cogs
        records.append(dict(month=row.month,sales=row.sales,days=days,supply_price=row.supply_price,purchases=purchases,purchase_cost=purchase_cost,gas_cogs=cogs,ft_capacity_day=row.ft_capacity_day,ft_cost=ft_cost,commodity_cost=commodity,brokerage_cost=brokerage,storage_cost=storage_cost,opex_cost=opex,opening_inventory=initial_inventory,injection=row.injection,credited_injection=credited_injection,withdrawal=row.withdrawal,withdrawal_delivered=withdrawal_delivery,closing_inventory=inventory,closing_inventory_book=book,withdrawal_cogs=withdrawal_cogs,cash_operating_cost=cash_cost,accounting_operating_cost=cogs+ft_cost+commodity+brokerage+storage_cost+opex,ft_unused_month=max(0,row.ft_capacity_day*days-purchases),ft_shortfall_month=max(0,purchases-row.ft_capacity_day*days)))
    result=pd.DataFrame(records).set_index('month')
    terminal_mode=config.get('terminal_mode','Sell at final forward price')
    if terminal_mode not in ['Sell at final forward price','Require zero inventory','Storage transfer']:raise ValueError('Unknown storage end-of-contract treatment.')
    terminal_price=float(result.supply_price.iloc[-1])
    if config.get('terminal_mode','Sell at final forward price')=='Require zero inventory' and inventory>1e-7:raise ValueError('The term ends with storage inventory. Choose terminal sale or enter withdrawals that empty storage.')
    terminal_sale=inventory*terminal_price if config.get('terminal_mode','Sell at final forward price')=='Sell at final forward price' else 0.
    terminal_gain=terminal_sale-book
    ft_credit=float(result.ft_cost.nlargest(2).mean())
    supply_credit=float(result.purchases.max()*max(0,result.supply_price.max()))
    return result,dict(opening_inventory_cost=opening*opening_unit,terminal_storage_proceeds=terminal_sale,terminal_storage_gain=terminal_gain,ft_credit=ft_credit,supply_credit=supply_credit,ending_inventory=inventory,ending_inventory_book=book,terminal_mode=terminal_mode,transferred_inventory=inventory if terminal_mode=='Storage transfer' else 0.,transferred_inventory_book=book if terminal_mode=='Storage transfer' else 0.)

def evaluate_utility(schedules, prices, configs, overhead, margin, discount=.1, capital_hurdle=.08, financing_days=30, manual_credit=None, return_credit=True, quote=None, sales_tax_rate=0.):
    if not np.isfinite(sales_tax_rate) or not 0<=sales_tax_rate<1:raise ValueError('Sales tax rate must be between 0% and less than 100%.')
    if margin is None or not np.isfinite(margin):raise ValueError('Enter the target margin.')
    if discount<0 or capital_hurdle<0 or financing_days<0:raise ValueError('Rates and financing days must be nonnegative.')
    details={};meta={}
    for route,schedule in schedules.items():details[route],meta[route]=route_build(schedule,prices[route],configs[route])
    index=next(iter(details.values())).index
    if not all(frame.index.equals(index) for frame in details.values()):raise ValueError('Supply paths must use the same contract months.')
    m=pd.DataFrame(index=index)
    for col in ['sales','purchase_cost','gas_cogs','ft_cost','commodity_cost','brokerage_cost','storage_cost','opex_cost','cash_operating_cost','accounting_operating_cost','ft_shortfall_month']:
        m[col]=sum(frame[col] for frame in details.values())
    h=pd.Series(overhead).reindex(index)
    if h.isna().any() or (h<0).any() or not np.isfinite(h).all():raise ValueError('Enter monthly allocated overhead for every contract month.')
    m['overhead']=h.to_numpy()
    m['capital_cost']=(m.cash_operating_cost+m.overhead).clip(lower=0)*capital_hurdle*financing_days/365
    m['cash_cost']=m.cash_operating_cost+m.overhead+m.capital_cost
    initial_inventory=sum(x['opening_inventory_cost'] for x in meta.values())
    terminal_storage=sum(x['terminal_storage_proceeds'] for x in meta.values())
    auto_credit=sum(x['ft_credit']+x['supply_credit'] for x in meta.values())
    credit=auto_credit if manual_credit is None else float(manual_credit)
    if credit<0:raise ValueError('Upfront credit must be nonnegative.')
    credit_recovery=credit if return_credit else 0.
    volume=float(m.sales.sum())
    if volume<=0:raise ValueError('Enter customer sales volumes above zero.')
    operating_floor=float((m.cash_cost.sum()+initial_inventory-terminal_storage)/volume)
    target=(operating_floor+float(margin))/(1-sales_tax_rate)
    operating_floor=operating_floor/(1-sales_tax_rate)
    fixed=target if quote is None else float(quote)
    m['customer_price']=fixed;m['revenue']=m.sales*fixed
    m['sales_tax']=m.revenue*sales_tax_rate
    m['net_sales_revenue']=m.revenue-m.sales_tax
    m['cash_cost']=m.cash_cost+m.sales_tax
    m['accounting_profit']=m.net_sales_revenue-m.accounting_operating_cost-m.overhead-m.capital_cost
    m['operating_cashflow']=m.revenue-m.cash_cost
    m['storage_terminal_cashflow']=0.;m.iloc[-1,m.columns.get_loc('storage_terminal_cashflow')]=terminal_storage
    m['credit_cashflow']=0.;m.iloc[-1,m.columns.get_loc('credit_cashflow')]=credit_recovery
    m['net_investment_cashflow']=m.operating_cashflow+m.storage_terminal_cashflow+m.credit_cashflow
    initial_outflow=credit+initial_inventory
    cash=np.r_[-initial_outflow,m.net_investment_cashflow.to_numpy()]
    npv,irr,status=monthly_returns(cash,discount)
    pv_volume=float(sum(v/(1+discount)**((i+1)/12) for i,v in enumerate(m.sales)))
    cash_without_revenue=np.r_[-initial_outflow,(-m.cash_cost+m.sales_tax+m.storage_terminal_cashflow+m.credit_cashflow).to_numpy()]
    pv_cost=-monthly_returns(cash_without_revenue,discount)[0]
    npv_floor=pv_cost/(pv_volume*(1-sales_tax_rate))
    profit=float(m.operating_cashflow.sum()-initial_inventory+terminal_storage)
    accounting_profit=float(m.accounting_profit.sum()+sum(x['terminal_storage_gain'] for x in meta.values()))
    if abs(profit-accounting_profit)>max(1e-5,abs(profit)*1e-9):raise ValueError('Inventory cash and profit reconciliation failed.')
    n=len(m)
    term_irr=(1+irr)**(n/12)-1 if irr is not None else None
    summary=dict(sales_tax_rate=sales_tax_rate,contract_sales_tax=float(m.sales_tax.sum()),contract_net_sales=float(m.net_sales_revenue.sum()),storage_transferred_volume=sum(x['transferred_inventory'] for x in meta.values()),storage_transferred_book=sum(x['transferred_inventory_book'] for x in meta.values()),term_irr=term_irr,term=n,target_price=target,offer_price=fixed,operating_break_even=operating_floor,npv_zero_price=npv_floor,contract_volume=volume,annual_revenue=float(m.revenue.sum()*12/n),contract_revenue=float(m.revenue.sum()),contract_profit=profit,annual_profit=profit*12/n,spread=profit/volume,gross_margin=profit/m.revenue.sum() if m.revenue.sum()>0 else None,npv=npv,irr=irr,irr_status=status,credit=credit,auto_credit=auto_credit,opening_inventory_cash=initial_inventory,total_initial_cash=initial_outflow,credit_recovery=credit_recovery,terminal_storage_proceeds=terminal_storage,overhead=float(m.overhead.sum()),shortfall_volume=float(m.ft_shortfall_month.sum()),discount=discount)
    audit=pd.DataFrame({'month_number':range(n+1),'net_cashflow':cash})
    audit['discount_factor']=1/(1+discount)**(audit.month_number/12)
    audit['present_value']=audit.net_cashflow*audit.discount_factor
    counts=[c.get('utility_customer_count', (c.get('campaign') or {}).get('customers')) for c in configs.values()]
    counts=[float(c) for c in counts if c is not None]
    if counts and (any(not np.isfinite(c) or c<=0 for c in counts) or any(abs(c-counts[0])>1e-8 for c in counts)):raise ValueError('Enter one consistent positive utility customer count.')
    customer_count=counts[0] if counts else None
    summary.update(customer_count=customer_count,contract_profit_per_customer=profit/customer_count if customer_count else None,annual_profit_per_customer=profit*12/n/customer_count if customer_count else None)
    return summary,m,details,meta,audit

